const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const eth = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017')
      .filter(ee.Filter.eq('country_na', 'Ethiopia'))
      .geometry();
    const splitLat = ee.Number(eth.centroid(1000).coordinates().get(1));
    const southRect = ee.Geometry.Rectangle([-180, -90, 180, splitLat], null, false);
    const northRect = ee.Geometry.Rectangle([-180, splitLat, 180, 90], null, false);
    const south = eth.intersection(southRect, 1);
    const north = eth.intersection(northRect, 1);

    const monthsFilter = ee.Filter.calendarRange(10, 11, 'month');
    const years = ee.List.sequence(2000, 2013);
    const yearCount = years.size();

    // 2. Data Acquisition & Check with fallback
    const monthlyId = 'UCSB-CHG/CHIRPS/Monthly';
    const dailyId = 'UCSB-CHG/CHIRPS/DAILY';
    let datasetName = 'CHIRPS Monthly';

    let monthly = ee.ImageCollection(monthlyId);
    let col2021_m = monthly.filterDate('2021-10-01', '2021-11-30').filter(monthsFilter);
    let base_m = monthly.filterDate('2000-01-01', '2013-12-31').filter(monthsFilter);

    async function evaluate(obj) {
      return await new Promise((resolve, reject) => obj.evaluate(resolve, reject));
    }

    const size2021_m = await evaluate(col2021_m.size());
    const sizeBase_m = await evaluate(base_m.size());

    let season2021;
    let seasonBase;

    if (size2021_m === 0 || sizeBase_m === 0) {
      // Fallback to CHIRPS Daily
      datasetName = 'CHIRPS Daily (fallback)';
      const daily = ee.ImageCollection(dailyId);
      const col2021_d = daily.filterDate('2021-10-01', '2021-11-30');
      const base_d = daily.filterDate('2000-01-01', '2013-12-31').filter(monthsFilter);
      const size2021_d = await evaluate(col2021_d.size());
      const sizeBase_d = await evaluate(base_d.size());
      console.log(`Monthly empty -> Fallback Daily | 2021 Items: ${size2021_d}, Baseline Items: ${sizeBase_d}`);
      if (size2021_d === 0 || sizeBase_d === 0) {
        console.log('C1');
        return;
      }
      season2021 = col2021_d.sum().rename('p');
      // Sum all Oct/Nov days from 2000-2013 then divide by number of years to get mean seasonal total
      seasonBase = base_d.sum().divide(ee.Number(yearCount)).rename('p');
    } else {
      season2021 = col2021_m.sum().rename('p');
      seasonBase = base_m.sum().divide(ee.Number(yearCount)).rename('p');
    }

    // 3. Processing and pixel counts (C2)
    const validMask = season2021.updateMask(seasonBase.mask());
    async function regionCount(img, region) {
      const dict = await evaluate(img.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: region,
        scale: 6000,
        maxPixels: 1e9,
        bestEffort: true
      }));
      return dict ? (dict.p || 0) : 0;
    }
    const northCount = await regionCount(validMask.rename('p'), north);
    const southCount = await regionCount(validMask.rename('p'), south);

    if ((northCount === 0) || (southCount === 0)) {
      console.log(`Valid Pixels - North: ${northCount}, South: ${southCount}`);
      console.log('C2');
      return;
    }

    // 4. Calculation of mean seasonal totals and ratios
    async function regionMean(img, region) {
      const dict = await evaluate(img.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: region,
        scale: 6000,
        maxPixels: 1e9,
        bestEffort: true
      }));
      return dict ? dict.p : null;
    }

    const n2021 = await regionMean(season2021, north);
    const nBase = await regionMean(seasonBase, north);
    const s2021 = await regionMean(season2021, south);
    const sBase = await regionMean(seasonBase, south);

    // 5. Validation (C3)
    function invalid(v) {
      return v === null || v === undefined || !isFinite(v);
    }
    if (invalid(n2021) || invalid(nBase) || invalid(s2021) || invalid(sBase) || nBase <= 0 || sBase <= 0) {
      console.log('C3');
      return;
    }

    const rNorth = n2021 / nBase;
    const rSouth = s2021 / sBase;

    // 6. Print concise evidence (<=20 lines)
    console.log(`Dataset: ${datasetName}`);
    console.log(`2021 Oct-Nov Items: ${size2021_m || 'n/a'}; Baseline Items: ${sizeBase_m || 'n/a'}; Years: ${await evaluate(yearCount)}`);
    console.log(`Valid Pixels - North: ${northCount}, South: ${southCount}`);
    console.log(`North 2021(mm): ${n2021.toFixed(1)}, LTA(mm): ${nBase.toFixed(1)}, Ratio: ${rNorth.toFixed(2)}`);
    console.log(`South 2021(mm): ${s2021.toFixed(1)}, LTA(mm): ${sBase.toFixed(1)}, Ratio: ${rSouth.toFixed(2)}`);
    console.log(`Ratio Diff (South-North): ${(rSouth - rNorth).toFixed(3)}`);

    // 7. Final Answer
    const tol = 0.01;
    if (rSouth + tol < rNorth) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (err) {
    console.error('Error:', err);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
